import subprocess
# Check Figure 1 is on pages 1-2
for page in [1, 2, 3]:
    result = subprocess.run(['pdftotext', '-f', str(page), '-l', str(page), 'main.pdf', '-'], capture_output=True, text=True)
    if 'Figure 1' in result.stdout or 'fig1' in result.stdout.lower():
        print(f'Figure 1 reference on page {page}')
    if 'three-panel' in result.stdout.lower() or 'taxonomy' in result.stdout.lower():
        print(f'Figure content on page {page}')
# Check page budget still OK
for page in [8, 9]:
    result = subprocess.run(['pdftotext', '-f', str(page), '-l', str(page), 'main.pdf', '-'], capture_output=True, text=True)
    lim_idx = result.stdout.find('Limitations')
    disc_idx = result.stdout.find('Discussion')
    if disc_idx > 0 or lim_idx > 0:
        print(f'Page {page}: Discussion@{disc_idx}, Limitations@{lim_idx}')
print()
result = subprocess.run(['pdfinfo', 'main.pdf'], capture_output=True, text=True)
for line in result.stdout.split('\n'):
    if 'Pages' in line:
